-- @usage follows
local usage = [[
LuaMacro 2.5.0, a Lua macro preprocessor and runner
    -l  require a library
    -e  statement to be executed
    -V  set a variable (-VX or -VY=1)
    -c  error context to be shown (default 2)
    -d  dump preprocessed output to stdout
    -o  write to this file
