    if args.input then
        arg = args
        arg[0] = args.input_name
        arg[-1] = 'luam'
        ok = subst_runstring(args.input,args.input_name,unpack(args)) ~= false
    elseif args.i then
        interactive_loop()
    end
end
os.exit(ok and 0 or 1)

-- END luam
